const r = await tools.pwsh({
  description: "Parse bilibili search results",
  command: `cd "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts"
$t = Get-Content "_b_bili_fuye.html" -Raw -Encoding UTF8
Write-Host "len=$($t.Length)"
[regex]::Matches($t,'<title>([\\s\\S]*?)</title>') | %{ $_.Groups[1].Value }
Write-Host "--- look for view counts ---"
[regex]::Matches($t,'"(play|video_review|danmaku|favorites|duration)":\\s*"?([0-9:]+)"?') | Select-Object -First 12 | %{ $_.Value }
Write-Host "--- plain text sample ---"
$plain = [regex]::Replace($t,'<script[\\s\\S]*?</script>','')
$plain = [regex]::Replace($plain,'<style[\\s\\S]*?</style>','')
$plain = [regex]::Replace($plain,'<[^>]+>',' ')
$plain = [regex]::Replace($plain,'\\s+',' ')
$plain.Substring(0,[Math]::Min(2500,$plain.Length))
`,
  timeoutMs: 90000
});
console.log(r.kind === "foreground" ? r.stdout.text + "\n---ERR---\n" + r.stderr.text : JSON.stringify(r));
